from hermes_tools import terminal
cmd = "python3 - <<'PY'
# Coordinates are zero-based; grid is 13x15. Interpret the 4x3 color-8 object
# as a plus with an extra lower stem: .8./888/.8./.8.
objects = {
 'color8_down_plus': (8, {(3,1),(4,0),(4,1),(4,2),(5,1),(6,1)}),
 'color2_plus': (2, {(10,1),(11,0),(11,1),(11,2),(12,1)}),
 'color3_outline3': (3, {(r,c) for r in range(2,5) for c in range(3,6) if r in (2,4) or c in (3,5)}),
 'color1_rect3x4': (1, {(r,c) for r in range(6,9) for c in range(4,8)}),
 'color1_outline5': (1, {(r,c) for r in range(6,11) for c in range(10,15) if r in (6,10) or c in (10,14)}),
}
settled = {}
# Stable packing: settle lower objects first, translating each rigid object down
# until its next step would hit the floor or any already-settled object.
for name, (color, cells) in sorted(objects.items(), key=lambda kv: max(r for r,c in kv[1][1]), reverse=True):
    moved = set(cells)
    while all(r + 1 < 13 and (r+1,c) not in set().union(*[v[1] for v in settled.values()]) for r,c in moved):
        moved = {(r+1,c) for r,c in moved}
    settled[name] = (color, moved)
    print(name, 'bbox=', (min(r for r,c in moved), max(r for r,c in moved), min(c for r,c in moved), max(c for r,c in moved)), 'shift=', min(r for r,c in moved)-min(r for r,c in cells))
grid = [[0]*15 for _ in range(13)]
for color, cells in settled.values():
    for r,c in cells:
        assert grid[r][c] == 0
        grid[r][c] = color
print('GRID')
for row in grid: print(row)
PY"
r = terminal(cmd, timeout=20)
print(r)

